def detect_intrusion(packet_log: list[dict]) -> list[dict]:
    from collections import defaultdict
    failed = defaultdict(int)
    ports = defaultdict(set)

    for p in packet_log:
        src = p.get("src_ip")
        if p.get("status") == "failed_login":
            failed[src] += 1
        ports[src].add(p.get("dst_port"))

    flagged = {ip for ip, n in failed.items() if n >= 5} | {ip for ip, s in ports.items() if len(s) >= 20}
    return [p for p in packet_log if p.get("src_ip") in flagged]
```

