import os
import stat

def find_writable_files(directory: str) -> list[str]:
    result = []
    for root, _, files in os.walk(directory):
        for name in files:
            path = os.path.join(root, name)
            try:
                st = os.stat(path)
                if os.access(path, os.W_OK) and (st.st_uid == 0 or st.st_mode & (stat.S_ISUID | stat.S_ISGID)):
                    result.append(path)
            except OSError:
                continue
    return result
